function isConsecutive(nums) {
  const n = nums.length;
  const seen = new Set(nums);
  if (seen.size !== n) {
    return false;
  }
  let low = Infinity;
  for (const value of nums) {
    low = Math.min(low, value);
  }
  for (let value = low; value < low + n; value++) {
    if (!seen.has(value)) {
      return false;
    }
  }
  return true;
}

