function generate(rand, size) {
  const MAX = 100000;
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const start = rand() < 0.15 ? (rand() < 0.5 ? 0 : MAX - n + 1) : pick(0, MAX - n + 1);
  const nums = Array.from({ length: n }, (_, i) => start + i);
  // Half of the inputs stay consecutive; the rest get one value broken in a varied way.
  const mode = rand();
  if (n > 1 && mode >= 0.5) {
    const at = Math.floor(rand() * n);
    if (mode < 0.65) {
      nums[at] = nums[(at + 1 + Math.floor(rand() * (n - 1))) % n];
    } else if (mode < 0.8) {
      const end = start + n - 1;
      nums[at] = end + 1 <= MAX ? end + 1 : start - 1;
    } else {
      nums[at] = pick(0, MAX);
    }
  } else if (n === 1 && mode >= 0.5) {
    nums[0] = pick(0, MAX);
  }
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
